import{_ as a,o as n,c as e,a0 as i}from"./chunks/framework.CNDWyMYS.js";const h=JSON.parse('{"title":"Installation instructions for Unix","description":"","frontmatter":{},"headers":[],"relativePath":"installation_instructions_for_unix.md","filePath":"installation_instructions_for_unix.md"}'),t={name:"installation_instructions_for_unix.md"};function l(o,s,p,r,c,u){return n(),e("div",null,[...s[0]||(s[0]=[i(`<h1 id="installation-instructions-for-unix" tabindex="-1">Installation instructions for Unix <a class="header-anchor" href="#installation-instructions-for-unix" aria-label="Permalink to &quot;Installation instructions for Unix&quot;">​</a></h1><p>The LuaRocks build system for Unix is based on a simple &quot;configure&quot; script and a Makefile.</p><h2 id="quick-start" tabindex="-1">Quick start <a class="header-anchor" href="#quick-start" aria-label="Permalink to &quot;Quick start&quot;">​</a></h2><p>To get a default installation of Lua and LuaRocks under <code>/usr/local</code>:</p><p>First, ensure that you have development tools installed on your system, otherwise run the command below to install them.</p><p>For Ubuntu/Debian systems, this should do it:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>sudo apt install build-essential libreadline-dev unzip</span></span></code></pre></div><p>For Yum-based distributions, try this:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>sudo yum install libtermcap-devel ncurses-devel libevent-devel readline-devel</span></span></code></pre></div><p>Then, to get Lua, either install it using your package manager of choice, or follow the instructions below.</p><ul><li><p>Download and unpack <a href="https://www.lua.org/ftp/" target="_blank" rel="noreferrer">latest Lua &quot;.tar.gz&quot; file</a>.</p></li><li><p>Go to the unpacked Lua directory.</p></li><li><p>To build and install Lua, run the following commands.</p></li></ul><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>make all test</span></span>
<span class="line"><span>sudo make install</span></span></code></pre></div><p>Once Lua and its dependencies are installed, it is time to install LuaRocks:</p><ul><li><p>Download and unpack <a href="https://luarocks.github.io/luarocks/releases/" target="_blank" rel="noreferrer">latest LuaRocks &quot;.tar.gz&quot; file</a>.</p></li><li><p>Go to the unpacked LuaRocks directory.</p></li><li><p>To configure, build and install LuaRocks, run the following commands. The <code>./configure</code> script will attempt to detect your installation of Lua. If you get any error messages, see the section &quot;<a href="#customizing-your-settings">Customizing your settings</a>&quot;, below.</p></li></ul><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>./configure --with-lua-include=/usr/local/include</span></span>
<span class="line"><span>make</span></span>
<span class="line"><span>sudo make install</span></span></code></pre></div><p>Installation should be done! Run <code>luarocks</code> with no arguments to see a summary of your settings.</p><p>This should be sufficient. For more information and installation options, read on.</p><h2 id="the-default-settings" tabindex="-1">The default settings <a class="header-anchor" href="#the-default-settings" aria-label="Permalink to &quot;The default settings&quot;">​</a></h2><p>The default settings are suitable for installing LuaRocks globally in your system while allowing both system-wide and per-user sets of rocks. User accounts will be able to install their own rocks in their $HOME directory, and the superuser can install rocks that will be available for everyone.</p><p>By default LuaRocks will install itself in <code>/usr/local</code>, like Lua, and will use <code>/usr/local/etc/luarocks/config.lua</code> as a default path for the configuration file. The default system-wide rocks trees is configured as <code>/usr/local/lib/luarocks</code>, and per-user rocks install at <code>$HOME/.luarocks/rocks/</code>. Command-line scripts provided by rocks will be installed in <code>/usr/local/lib/luarocks/bin/</code> or <code>$HOME/.luarocks/bin/</code>, respectively. The user may then add these directories to their <code>$PATH</code> variable.</p><h2 id="customizing-your-settings" tabindex="-1">Customizing your settings <a class="header-anchor" href="#customizing-your-settings" aria-label="Permalink to &quot;Customizing your settings&quot;">​</a></h2><p>All paths described above can be overridden with flags in the <code>configure</code> script, or entries in the configuration file. These are the supported flags, as presented by the <code>--help</code> option:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Installation directories:</span></span>
<span class="line"><span>  --prefix=PREFIX              Directory where LuaRocks should be installed,</span></span>
<span class="line"><span>                               Default is &#39;/usr/local&#39;</span></span>
<span class="line"><span></span></span>
<span class="line"><span>By default, \`make install&#39; will install all the files in \`/usr/local&#39;,</span></span>
<span class="line"><span>\`/usr/local/lib&#39; etc.  You can specify an installation prefix other than</span></span>
<span class="line"><span>\`/usr/local/&#39; using \`--prefix&#39;, for instance \`--prefix=$HOME&#39;.</span></span>
<span class="line"><span></span></span>
<span class="line"><span>For better control, use the options below.</span></span>
<span class="line"><span></span></span>
<span class="line"><span>Fine tuning of the installation directories:</span></span>
<span class="line"><span>  --sysconfdir=SYSCONFDIR      Directory for single-machine config.</span></span>
<span class="line"><span>                               Default is PREFIX/etc</span></span>
<span class="line"><span></span></span>
<span class="line"><span>Where to install files provided by rocks:</span></span>
<span class="line"><span>  --rocks-tree=DIR             Root of the local tree of installed rocks.</span></span>
<span class="line"><span>                               To make files installed in this location</span></span>
<span class="line"><span>                               accessible to Lua and your $PATH, see</span></span>
<span class="line"><span>                               &quot;luarocks path --help&quot; after installation.</span></span>
<span class="line"><span>                               Avoid using paths controlled by your</span></span>
<span class="line"><span>                               system&#39;s package manager, such as /usr.</span></span>
<span class="line"><span>                               - Default is PREFIX</span></span>
<span class="line"><span></span></span>
<span class="line"><span>Where is your Lua interpreter:</span></span>
<span class="line"><span>  --lua-version=VERSION        Use specific Lua version: 5.1, 5.2, 5.3, or 5.4</span></span>
<span class="line"><span>                               - Default is auto-detected.</span></span>
<span class="line"><span>  --with-lua-bin=LUA_BINDIR    Location of your Lua binar(y/ies).</span></span>
<span class="line"><span>                               - Default is the directory of the</span></span>
<span class="line"><span>                               auto-detected Lua interpreter,</span></span>
<span class="line"><span>                               (or DIR/bin if --with-lua is used)</span></span>
<span class="line"><span>  --with-lua=LUA_DIR           Use Lua from given directory. Default is LUA_BINDIR/..</span></span>
<span class="line"><span>  --with-lua-include=DIR       Lua&#39;s includes dir. Default is LUA_DIR/include</span></span>
<span class="line"><span>  --with-lua-lib=DIR           Lua&#39;s libraries dir. Default is LUA_DIR/lib</span></span>
<span class="line"><span>  --with-lua-interpreter=NAME  Lua interpreter name.</span></span>
<span class="line"><span>                               - Default is to auto-detected</span></span>
<span class="line"><span></span></span>
<span class="line"><span>For specialized uses of LuaRocks:</span></span>
<span class="line"><span>  --force-config               Force using a single config location.</span></span>
<span class="line"><span>                               Do not honor the $LUAROCKS_CONFIG_5_x</span></span>
<span class="line"><span>                               or $LUAROCKS_CONFIG environment</span></span>
<span class="line"><span>                               variable or the user&#39;s local config.</span></span>
<span class="line"><span>                               Useful to avoid conflicts when LuaRocks</span></span>
<span class="line"><span>                               is embedded within an application.</span></span>
<span class="line"><span>  --disable-incdir-check       If you do not wish to use &quot;luarocks build&quot;,</span></span>
<span class="line"><span>                               (e.g. when only deploying binary packages)</span></span>
<span class="line"><span>                               you do not need lua.h installed. This flag</span></span>
<span class="line"><span>                               skips the check for lua.h in &quot;configure&quot;.</span></span></code></pre></div><p>After installation, a default config file called config.lua will be installed at the directory defined by <code>--sysconfdir</code>. For further configuration of LuaRocks paths, see the <a href="./config_file_format.html">Config file format</a>.</p><h2 id="next-steps" tabindex="-1">Next steps <a class="header-anchor" href="#next-steps" aria-label="Permalink to &quot;Next steps&quot;">​</a></h2><p>Once LuaRocks is installed, learn more about <a href="./using_luarocks.html">using LuaRocks</a>.</p>`,26)])])}const f=a(t,[["render",l]]);export{h as __pageData,f as default};
